def shifted(points, d): return {(r+d[0],c+d[1]) for r,c in points}
def within(s,d):
    pts=shifted(s['color']|s['mark'],d)
    return all(0<=r<26 and 0<=c<26 for r,c in pts)

def valid_place(name,d,placed):
    s=shapes[name]; cc=shifted(s['color'],d); mm=shifted(s['mark'],d)
    prior_c=set(); prior_m=collections.Counter()
    for nm,nd in placed.items():
        prior_c |= shifted(shapes[nm]['color'],nd)
        prior_m.update(shifted(shapes[nm]['mark'],nd))
    if cc & prior_c or cc & set(prior_m) or mm & prior_c: return False
    if any(prior_m[p]>=2 for p in mm): return False
    return True

def candidates(name,placed):
    occ=collections.Counter()
    for nm,d in placed.items(): occ.update(shifted(shapes[nm]['mark'],d))
    coords=[p for p,n in occ.items() if n==1]
    shifts=set()
    for mr,mc in shapes[name]['mark']:
        for r,c in coords:
            d=(r-mr,c-mc)
            if within(shapes[name],d) and valid_place(name,d,placed): shifts.add(d)
    return sorted(shifts)

nodes=0; solutions=[]; max_solutions=5000

def recurse(placed):
    global nodes
    nodes += 1
    if len(placed)==len(shapes):
        occ=collections.Counter()
        for nm,d in placed.items(): occ.update(shifted(shapes[nm]['mark'],d))
        if all(v==2 for v in occ.values()):
            solutions.append(dict(placed))
        return
    remaining=[n for n in shapes if n not in placed]
    opts={n:candidates(n,placed) for n in remaining}
    opts={n:v for n,v in opts.items() if v}
    if not opts: return
    # choose least currently available branching factor
    name=min(opts,key=lambda n:len(opts[n]))
    for d in opts[name]:
        placed[name]=d
        recurse(placed)
        del placed[name]
        if len(solutions)>=max_solutions: return

